window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ea4a7aeab33db685"]={"versions": [{"id": "FIG-ea4a7aeab33db685", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Mka (MACsec Key Agreement) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die Metadatenstruktur des Konfigurationscontainers <code>MkaKay</code> (MACsec Key Agreement Entity) mit seinen untergeordneten Parametern, Literalen und Sub-Containern gemäß der AUTOSAR-ECUC-Metamodell-Methodik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>MkaKay: EcucParamConfContainerDef</code></strong>: Zentraler Konfigurationscontainer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+parameter</code>:</li>\n<li><strong><code>MkaSrcMacAddress: EcucStringParamDef</code></strong>: Quell-MAC-Adresse mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaDstMacAddress: EcucStringParamDef</code></strong>: Ziel-MAC-Adresse mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaRole: EcucEnumerationParamDef</code></strong>: Rollendefinition der KaY-Instanz mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>. Enthält über <code>+literal</code>:</li>\n<li><strong><code>MKA_KEY_SERVER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MKA_PEER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MkaKeyServerPriority: EcucIntegerParamDef</code></strong>: Priorität für die Key-Server-Auswahl mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaBypassVlan: EcucIntegerParamDef</code></strong>: VLAN-Bypass-Konfiguration mit Wertebereich <code>min = 0</code>, <code>max = 4094</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 255</code>.</li>\n<li><strong><code>MkaBypassEtherType: EcucIntegerParamDef</code></strong>: EtherType-Bypass-Konfiguration mit Wertebereich <code>min = 0</code>, <code>max = 65535</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 255</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+subContainer</code>:</li>\n<li><strong><code>MkaKayParticipant: EcucParamConfContainerDef</code></strong>: Sub-Container für MKA-Teilnehmer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 255</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische ECU-Konfigurationsbeschreibung (ECUC Parameter Definition) stellt das Diagramm kein dynamisches Laufzeitverhalten und keine Sequenzabläufe dar. Es definiert die statischen Beschränkungen, Typisierungen und Kardinalitäten, die während des Konfigurations-, Validierungs- und Codegenerierungsprozesses des Mka-Treibers bzw. -Stacks zur Build-Zeit ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellten Container-, Parameter- und Literaldefinitionen sind normativ für die Konfigurationswerkzeuge und Codegeneratoren des AUTOSAR-Moduls Mka. Die Einhaltung der angegebenen Multiplizitäten und Wertebereiche (z. B. <code>MkaBypassVlan</code> im Bereich 0 bis 4094, <code>MkaBypassEtherType</code> im Bereich 0 bis 65535, <code>MkaKeyServerPriority</code> im Bereich 0 bis 255) ist bei der Generierung der ECU-Konfigurationsbeschreibungen (ARXML) zwingend zu validieren. Optionale Parameter (<code>lowerMultiplicity = 0</code>) dürfen entfallen, während Parameter mit <code>lowerMultiplicity = 1</code> obligatorisch konfiguriert werden müssen. Multiplizitäten bis 255 ermöglichen Listenkonfigurationen für Bypässe und Teilnehmer.</p>"}, {"id": "FIG-de21a00e99d4f546", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Mka (MACsec Key Agreement) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die Metadatenstruktur des Konfigurationscontainers <code>MkaKay</code> (MACsec Key Agreement Entity) mit seinen untergeordneten Parametern, Literalen und Sub-Containern gemäß der AUTOSAR-ECUC-Metamodell-Methodik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>MkaKay: EcucParamConfContainerDef</code></strong>: Zentraler Konfigurationscontainer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+parameter</code>:</li>\n<li><strong><code>MkaSrcMacAddress: EcucStringParamDef</code></strong>: Quell-MAC-Adresse mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaDstMacAddress: EcucStringParamDef</code></strong>: Ziel-MAC-Adresse mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaRole: EcucEnumerationParamDef</code></strong>: Rollendefinition der KaY-Instanz mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>. Enthält über <code>+literal</code>:</li>\n<li><strong><code>MKA_KEY_SERVER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MKA_PEER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MkaKeyServerPriority: EcucIntegerParamDef</code></strong>: Priorität für die Key-Server-Auswahl mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaBypassVlan: EcucIntegerParamDef</code></strong>: VLAN-Bypass-Konfiguration mit Wertebereich <code>min = 0</code>, <code>max = 4094</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 255</code>.</li>\n<li><strong><code>MkaBypassEtherType: EcucIntegerParamDef</code></strong>: EtherType-Bypass-Konfiguration mit Wertebereich <code>min = 0</code>, <code>max = 65535</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 255</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+subContainer</code>:</li>\n<li><strong><code>MkaKayParticipant: EcucParamConfContainerDef</code></strong>: Sub-Container für MKA-Teilnehmer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 255</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische ECU-Konfigurationsbeschreibung (ECUC Parameter Definition) stellt das Diagramm kein dynamisches Laufzeitverhalten und keine Sequenzabläufe dar. Es definiert die statischen Beschränkungen, Typisierungen und Kardinalitäten, die während des Konfigurations-, Validierungs- und Codegenerierungsprozesses des Mka-Treibers bzw. -Stacks zur Build-Zeit ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellten Container-, Parameter- und Literaldefinitionen sind normativ für die Konfigurationswerkzeuge und Codegeneratoren des AUTOSAR-Moduls Mka. Die Einhaltung der angegebenen Multiplizitäten und Wertebereiche (z. B. <code>MkaBypassVlan</code> im Bereich 0 bis 4094, <code>MkaBypassEtherType</code> im Bereich 0 bis 65535, <code>MkaKeyServerPriority</code> im Bereich 0 bis 255) ist bei der Generierung der ECU-Konfigurationsbeschreibungen (ARXML) zwingend zu validieren. Optionale Parameter (<code>lowerMultiplicity = 0</code>) dürfen entfallen, während Parameter mit <code>lowerMultiplicity = 1</code> obligatorisch konfiguriert werden müssen. Multiplizitäten bis 255 ermöglichen Listenkonfigurationen für Bypässe und Teilnehmer.</p>"}, {"id": "FIG-c1ddd2dc79beccc3", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsmodells (ECUC Parameter Configuration Container Definition) für das BSW-Modul Mka (MACsec Key Agreement) innerhalb der AUTOSAR Classic Platform. Das Diagramm modelliert die Metadatenstruktur des Konfigurationscontainers <code>MkaKay</code> (MACsec Key Agreement Entity) mit seinen untergeordneten Parametern, Literalen und Sub-Containern gemäß der AUTOSAR-ECUC-Metamodell-Methodik.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>MkaKay: EcucParamConfContainerDef</code></strong>: Zentraler Konfigurationscontainer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+parameter</code>:</li>\n<li><strong><code>MkaDstMacAddress: EcucStringParamDef</code></strong>: Ziel-MAC-Adresse mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>.</li>\n<li><strong><code>MkaRole: EcucEnumerationParamDef</code></strong>: Rollendefinition der KaY-Instanz mit <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code>. Enthält über <code>+literal</code>:</li>\n<li><strong><code>MKA_KEY_SERVER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MKA_PEER: EcucEnumerationLiteralDef</code></strong></li>\n<li><strong><code>MkaKeyServerPriority: EcucIntegerParamDef</code></strong>: Priorität für die Key-Server-Auswahl mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Multiplizität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n<li>Enthält über die Kompositionsbeziehung <code>+subContainer</code>:</li>\n<li><strong><code>MkaKayParticipant: EcucParamConfContainerDef</code></strong>: Sub-Container für MKA-Teilnehmer mit Multiplizität <code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 255</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische ECU-Konfigurationsbeschreibung (ECUC Parameter Definition) stellt das Diagramm kein dynamisches Laufzeitverhalten und keine Sequenzabläufe dar. Es definiert die statischen Beschränkungen, Typisierungen und Kardinalitäten, die während des Konfigurations-, Validierungs- und Codegenerierungsprozesses des Mka-Treibers bzw. -Stacks zur Build-Zeit ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die dargestellten Container-, Parameter- und Literaldefinitionen sind normativ für die Konfigurationswerkzeuge und Codegeneratoren des AUTOSAR-Moduls Mka. Die Einhaltung der angegebenen Multiplizitäten und Wertebereiche (z. B. <code>MkaKeyServerPriority</code> im Bereich 0 bis 255 mit <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code> sowie <code>MkaDstMacAddress</code> und <code>MkaRole</code> mit Multiplizität 1) ist bei der Validierung und ARXML-Generierung verbindlich. Der Sub-Container <code>MkaKayParticipant</code> erfordert mindestens eine und maximal 255 Instanzen je KaY-Entität.</p>"}], "trans": [{"from": "FIG-ea4a7aeab33db685", "to": "FIG-de21a00e99d4f546", "fr": "R22-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-de21a00e99d4f546", "to": "FIG-c1ddd2dc79beccc3", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>MkaSrcMacAddress: EcucStringParamDef</code> entfällt.</li>\n<li>Parameter <code>MkaBypassVlan: EcucIntegerParamDef</code> entfällt.</li>\n<li>Parameter <code>MkaBypassEtherType: EcucIntegerParamDef</code> entfällt.</li>\n</ul>"}]};
